/**
 * Golden conformance tests: the TS engine must reproduce the canonical
 * Python engine's outputs (test/goldens.json, generated by scripts/gen_goldens.py).
 */
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const initSqlJs = require("sql.js");
const { OorepEngine } = require("../dist/main/engine.js");

const goldens = JSON.parse(fs.readFileSync(path.join(ROOT, "test", "goldens.json"), "utf8"));

let engine;
test.before(async () => {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync(path.join(ROOT, "data", "oorep.sqlite"));
  const db = new SQL.Database(buf);
  engine = new OorepEngine(db);
  const t0 = Date.now();
  engine.load();
  console.log(`engine loaded in ${Date.now() - t0} ms`);
});

test("stats match the source project", () => {
  const s = engine.getStats();
  assert.equal(s.remedies, 2432);
  assert.equal(s.rubricsDistinct, 74785);
  assert.equal(s.links, 1359572);
  assert.equal(s.vectorRows, 74667);
  assert.equal(s.cycles, 604);
});

for (const g of goldens.hybrid) {
  test(`hybrid search: "${g.query}"`, () => {
    const res = engine.searchRubricsHybrid(g.query, 10);
    assert.equal(res.length, g.results.length, "result count");
    // Per-rank strict where the score is unique in the window; tie groups
    // (exact equal scores) compared as unordered sets — numpy's argpartition
    // and JS's stable sort legitimately order equal-scored rows differently.
    const counts = new Map();
    for (const r of [...res, ...g.results.map((x) => ({ score: x.hybrid }))]) {
      counts.set(r.score, (counts.get(r.score) ?? 0) + 1);
    }
    for (let i = 0; i < g.results.length; i++) {
      const py = g.results[i];
      const ts = res[i];
      assert.ok(Math.abs(ts.score - py.hybrid) < 1e-4, `rank ${i + 1} score ${ts.score} vs ${py.hybrid}`);
      if ((counts.get(ts.score) ?? 0) === 1 || (counts.get(py.hybrid) ?? 0) === 1) {
        assert.equal(ts.id, py.id, `rank ${i + 1} id (unique score)`);
        assert.equal(ts.fullpath, py.fullpath, `rank ${i + 1} fullpath`);
        assert.equal(ts.source, py.source, `rank ${i + 1} source`);
      }
    }
    const tsIds = res.map((r) => r.id).sort((a, b) => a - b);
    const pyIds = g.results.map((r) => r.id).sort((a, b) => a - b);
    assert.deepEqual(tsIds, pyIds, "id multiset");
  });
}

for (const g of goldens.vector) {
  test(`vector search: "${g.query}"`, () => {
    const res = engine.searchRubricsVector(g.query, 10);
    assert.equal(res.length, Math.min(10, g.results.length), "result count");
    // numpy argpartition vs JS stable sort break exact score ties differently,
    // so per-rank ids are only asserted where the score is unique. Every TS id
    // must exist in the Python wide (top-30) ranking with the same score.
    const wide = new Map(g.wide.map((w) => [w.id, w.score]));
    const scoreCount = new Map();
    for (const w of g.wide) scoreCount.set(w.score, (scoreCount.get(w.score) ?? 0) + 1);
    for (let i = 0; i < Math.min(10, g.results.length); i++) {
      const py = g.results[i];
      const ts = res[i];
      assert.ok(Math.abs(ts.score - py.score) < 2e-3, `rank ${i + 1} score ${ts.score} vs ${py.score}`);
      const pyWideScore = wide.get(ts.id);
      assert.ok(pyWideScore !== undefined, `rank ${i + 1} ts id ${ts.id} present in py wide ranking`);
      assert.ok(Math.abs(pyWideScore - ts.score) < 2e-3, `rank ${i + 1} ts id ${ts.id} score matches py wide`);
      if ((scoreCount.get(py.score) ?? 0) === 1) {
        assert.equal(ts.id, py.id, `rank ${i + 1} id (unique score)`);
      }
    }
    // ranks 1..k with strictly decreasing scores must match ids exactly
    for (let i = 0; i < g.results.length; i++) {
      if ((scoreCount.get(g.results[i].score) ?? 0) === 1) {
        assert.equal(res[i].id, g.results[i].id, `unique-score rank ${i + 1}`);
      }
    }
  });
}

for (const g of goldens.lexical) {
  test(`lexical search: "${g.query}"`, () => {
    const res = engine.searchRubricsLexical(g.query, 10);
    assert.equal(res.length, g.results.length, "result count");
    for (let i = 0; i < g.results.length; i++) {
      assert.equal(res[i].id, g.results[i].id, `rank ${i + 1} id`);
      assert.ok(Math.abs(res[i].score - g.results[i].match) < 1e-6, `rank ${i + 1} score`);
    }
  });
}

for (const g of goldens.repertorize) {
  test(`repertorize: [${g.symptoms.join(", ")}]`, () => {
    const res = engine.repertorize(g.symptoms, { topN: 15, withCycles: false, fullMatches: true });
    assert.equal(res.length, g.results.length, "result count");
    for (let i = 0; i < g.results.length; i++) {
      const want = g.results[i];
      const got = res[i];
      assert.equal(got.abbrev, want.abbrev, `rank ${i + 1} abbrev (got ${got.abbrev}, want ${want.abbrev})`);
      assert.equal(got.score, want.score, `rank ${i + 1} score (got ${got.score}, want ${want.score})`);
      assert.equal(got.match_count, want.match_count, `rank ${i + 1} match_count`);
      assert.equal(got.name, want.name, `rank ${i + 1} name`);
      // Full-match multiset from the Python reconstruction (untruncated,
      // order-independent): every (symptom, rubric_id, weight) contribution.
      const key = (m) => `${m.query_symptom}|${m.rubric_id}|${m.weight}`;
      const tsM = got.matches.map(key).sort();
      const pyM = want.full_matches.map((m) => `${m[0]}|${m[1]}|${m[2]}`).sort();
      assert.deepEqual(tsM, pyM, `rank ${i + 1} full match multiset`);
    }
  });
}

for (const g of goldens.repertorize) {
  test(`repertorize cycles: [${g.symptoms.join(", ")}]`, () => {
    const res = engine.repertorize(g.symptoms, { topN: 15 });
    for (let i = 0; i < g.results.length; i++) {
      const wc = g.results[i].cycle;
      const gc = res[i].cycle_analysis;
      if (!wc || !wc.remedy_cycle) {
        assert.ok(!gc || !gc.remedy_cycle, `rank ${i + 1} expected no cycle`);
        continue;
      }
      assert.ok(gc, `rank ${i + 1} cycle_analysis present`);
      assert.equal(gc.remedy_cycle, wc.remedy_cycle, `rank ${i + 1} cycle remedy`);
      assert.equal(gc.segments_matched_count, wc.segments_matched_count, `rank ${i + 1} segments matched`);
      assert.equal(gc.total_segments, wc.total_segments, `rank ${i + 1} total segments`);
      assert.equal(gc.segment_coverage, wc.segment_coverage, `rank ${i + 1} segment coverage`);
      assert.equal(gc.meets_threshold, wc.meets_threshold, `rank ${i + 1} meets_threshold`);
    }
  });
}

test("clinical mapper: synonym expansion", () => {
  const n = engine.normalizeSymptom("can't sleep, thirsty in small sips");
  assert.ok(n.expanded_terms.includes("sleep"));
  assert.ok(n.expanded_terms.includes("sleeplessness"));
  assert.ok(n.expanded_terms.includes("thirst"));
  assert.ok(n.expanded_terms.includes("small quantities"));
});

test("suggestCandidates requires remedies and ranks", () => {
  const cands = engine.suggestCandidates("headache morning", 8);
  assert.ok(cands.length > 0 && cands.length <= 8);
  for (const c of cands) assert.ok(c.remedy_count > 0);
  assert.equal(cands[0].rank, 1);
});

test("remedy search + abbrev lookup", () => {
  const hits = engine.searchRemedies("arsenic", 5);
  assert.ok(hits.some((h) => h.abbrev === "Ars."));
  const ars = engine.getRemedyByAbbrev("Ars.");
  assert.equal(ars.name.toLowerCase(), "arsenicum album");
});

test("cycle retrieval for Calc.", () => {
  const c = engine.getCycle("Calc.");
  assert.ok(c);
  assert.ok(c.segments.length >= 3);
  const m = engine.matchCaseToCycle(["coldness of feet", "cramps in legs", "swelling"], c);
  assert.ok(m.matched_segments.length >= 1);
});
